1. //! Provides sequentially-consistent atomic memory locations with associated ghost state.
2. //! See the [`atomic_with_ghost!`] documentation for more information.
3. #![allow(unused_imports)]
4. 
5. use super::atomic::*;
6. use super::invariant::*;
7. use super::modes::*;
8. use super::prelude::*;
